function VideoPlayer({ video }: { video: Video }) {
  const { url, loading, error } = useVideoBlobUrl(video.id);
  const [loop, setLoop] = useState(readLoopPreference);

  const toggleLoop = useCallback(() => {
    setLoop((prev) => {
      const next = !prev;
      writeLoopPreference(next);
      return next;
    });
  }, []);

  if (loading) {
    return <p className="muted">Loading video…</p>;
  }
  if (error || !url) {
    return <p className="login-error">{error ?? 'Video unavailable.'}</p>;
  }

  return (
    <div className="video-player-wrap">
      <video
        className="video-player"
        controls
        loop={loop}
        src={url}
        preload="metadata"
        aria-label={video.title}
      />
      <div className="video-player-controls">
        <button
          type="button"
          className={loop ? 'chip chip--active' : 'chip'}
          aria-pressed={loop}
          onClick={toggleLoop}
        >
          Loop
        </button>
      </div>
    </div>
  );
}

